const buildGiantPyramid = async (bot) => {
  // Get the current position of the bot
  const pos = world.getPosition(bot);

  // Define the size of the pyramid's base
  const baseSize = 21;

  // Define the block type for the pyramid
  const blockType = 'sandstone';

  // Loop to create each layer of the pyramid
  for (let y = 0; y < baseSize / 2; y++) {
    for (let x = 0; x < baseSize - 2 * y; x++) {
      for (let z = 0; z < baseSize - 2 * y; z++) {
        await skills.placeBlock(bot, blockType, pos.x + x - Math.floor(baseSize / 2) + y, pos.y + y, pos.z + z - Math.floor(baseSize / 2) + y);
      }
    }
  }
};

await buildGiantPyramid(bot);
