// Inventory check function
async function checkInventory(bot, requiredItems) {
    const inventory = await world.getInventoryCounts(bot);
    const missingItems = {};

    for (const [item, count] of Object.entries(requiredItems)) {
        if (!inventory[item] || inventory[item] < count) {
            missingItems[item] = count - (inventory[item] || 0);
        }
    }

    return missingItems;
}

// Gather materials function
async function gatherMaterials(bot, materials) {
    for (const [item, count] of Object.entries(materials)) {
        let collected = 0;
        while (collected < count) {
            const success = await skills.collectBlock(bot, item, count - collected);
            if (success) {
                collected += count;
            } else {
                break;
            }
        }
    }
}

