// Step 1: Check the inventory for necessary materials
let inventory = world.getInventoryCounts(bot);
let requiredMaterials = {
    oak_planks: 100,
    cobblestone: 50,
    glass_pane: 10,
    door: 1,
    torch: 20
};

function materialsMissing(currentInventory, required) {
    for (let item in required) {
        if (currentInventory[item] === undefined || currentInventory[item] < required[item]) {
            return true;
        }
    }
    return false;
}

// Step 2: Craft missing materials if possible
async function craftMissingMaterials() {
    let crafted = false;
    if ((inventory['oak_planks'] || 0) < requiredMaterials.oak_planks && (inventory['oak_log'] || 0) >= (requiredMaterials.oak_planks / 4)) {
        await skills.craftRecipe(bot, "planks");
        crafted = true;
    }
    if ((inventory['glass_pane'] || 0) < requiredMaterials.glass_pane && (inventory['glass_block'] || 0) >= (requiredMaterials.glass_pane / 6)) {
        await skills.craftRecipe(bot, "glass_pane");
        crafted = true;
    }
    return crafted;
}

// Step 3: Gather missing materials
