    if ((inventory['oak_planks'] || 0) < requiredMaterials.oak_planks) {
        await skills.collectBlock(bot, "oak_log", requiredMaterials.oak_planks / 4);
        await skills.craftRecipe(bot, "planks");
    }
    if ((inventory['cobblestone'] || 0) < requiredMaterials.cobblestone) {
        await skills.collectBlock(bot, "cobblestone", requiredMaterials.cobblestone);
    }
    if ((inventory['glass_pane'] || 0) < requiredMaterials.glass_pane) {
        await skills.collectBlock(bot, "sand", requiredMaterials.glass_pane / 6);
        await skills.smeltItem(bot, "sand", requiredMaterials.glass_pane / 6);
        await skills.craftRecipe(bot, "glass_pane");
    }
    if ((inventory['door'] || 0) < requiredMaterials.door) {
        await skills.craftRecipe(bot, "door");
    }
    if ((inventory['torch'] || 0) < requiredMaterials.torch) {
        await skills.craftRecipe(bot, "torch");
