const position = world.getPosition(bot);
const startX = position.x;
const startY = position.y;
const startZ = position.z;
const maxHeight = 310;

// Define block types to use
const blockTypes = ['stone', 'stone_bricks', 'cobblestone'];
let currentHeight = startY;

while (currentHeight - startY < maxHeight) {
    for (let i = 0; i < blockTypes.length; i++) {
        let diameter = 30 - i;
        if (diameter < 3) diameter = 3; // Minimum diameter

        // Define height of each layer
        const layerHeight = Math.floor(Math.random() * 9) + 8; // Between 8 and 16

        for (let y = currentHeight; y < currentHeight + layerHeight && y - startY < maxHeight; y++) {
            // Build walls
            for (let x = startX - diameter; x <= startX + diameter; x++) {
                for (let z = startZ - diameter; z <= startZ + diameter; z++) {
                    const dist = Math.sqrt(Math.pow(x - startX, 2) + Math.pow(z - startZ, 2));
                    if (dist <= diameter) {
                        await skills.placeBlock(bot, blockTypes[i], x, y, z);
                    }
                }
            }
        }

        currentHeight += layerHeight;
        if (currentHeight - startY >= maxHeight) break;
    }
}
