// Build the wooden house
async function buildHouse() {
    // Create corners with oak logs
    for (let x = 0; x < width; x++) {
        for (let y = 0; y < height; y++) {
            for (let z = 0; z < depth; z++) {
                if ((x === 0 || x === width - 1) && (z === 0 || z === depth - 1)) {
                    await skills.placeBlock(bot, 'oak_log', startX + x, startY + y, startZ + z);
                }
            }
        }
    }

    // Create walls with oak planks and add windows
    for (let x = 0; x < width; x++) {
        for (let y = 0; y < height; y++) {
            for (let z = 0; z < depth; z++) {
                if (x === 0 || x === width - 1 || z === 0 || z === depth - 1) {
                    if (y === 1 && (z === 2 || z === 4) && x !== 0 && x !== width - 1) {
                        await skills.placeBlock(bot, 'glass', startX + x, startY + y, startZ + z);
                    } else if (!((x === 0 || x === width - 1) && (z === 0 || z === depth - 1))) {
                        await skills.placeBlock(bot, 'oak_planks', startX + x, startY + y, startZ + z);
                    }
                }
            }
        }
    }

    // Create door
    await skills.placeBlock(bot, 'oak_door', startX + Math.floor(width / 2), startY, startZ);

    // Create sloped roof
    for (let layer = 0; layer < 3; layer++) {
        for (let x = layer; x < width - layer; x++) {
            for (let z = layer; z < depth - layer; z++) {
                await skills.placeBlock(bot, 'oak_stairs', startX + x, startY + height + layer, startZ + z);
            }
        }
    }
}

