async function buildStraightSection(bot, length) {
    for (let i = 0; i < length; i++) {
        await skills.placeBlock(bot, 'oak_planks', baseX + i, baseY, baseZ);
        await skills.placeBlock(bot, 'rail', baseX + i, baseY + 1, baseZ);
    }
    baseX += length;
}

async function buildTurn(bot, direction) {
    const turn = direction === 'left' ? [-1, 1] : [1, 1];

    await skills.placeBlock(bot, 'oak_planks', baseX, baseY, baseZ + turn[0]);
    await skills.placeBlock(bot, 'rail', baseX, baseY + 1, baseZ + turn[0]);

    await skills.placeBlock(bot, 'oak_planks', baseX + turn[1], baseY, baseZ + turn[0]);
    await skills.placeBlock(bot, 'rail', baseX + turn[1], baseY + 1, baseZ + turn[0]);

    baseX += turn[1];
    baseZ += turn[0];
}

async function buildUpSlope(bot, steps) {
    for (let i = 0; i < steps; i++) {
        await skills.placeBlock(bot, 'oak_planks', baseX, baseY, baseZ + i);
        await skills.placeBlock(bot, 'oak_planks', baseX, baseY + 1 + i, baseZ + i);
        await skills.placeBlock(bot, 'rail', baseX, baseY + 2 + i, baseZ + i);
    }
    baseZ += steps;
    baseY += steps;
}

async function buildRollerCoaster(bot) {
    await buildStraightSection(bot, 20);
    await buildUpSlope(bot, 5);
    await buildTurn(bot, 'left');
    await buildStraightSection(bot, 10);
    await buildTurn(bot, 'right');
    await buildUpSlope(bot, 5);
    await buildStraightSection(bot, 15);
}

