let pos = world.getPosition(bot);

// Define the castle dimensions
const castleWidth = 10;
const castleDepth = 10;
const wallHeight = 5;
const towerHeight = 7;
const towerRadius = 2;

// Function to place a block
async function placeBlock(type, x, y, z) {
  await skills.placeBlock(bot, type, x, y, z);
}

// Build the castle walls
async function buildWalls() {
  for (let x = pos.x; x < pos.x + castleWidth; x++) {
    for (let y = pos.y; y < pos.y + wallHeight; y++) {
      await placeBlock("stone_bricks", x, y, pos.z);
      await placeBlock("stone_bricks", x, y, pos.z + castleDepth - 1);
    }
  }

  for (let z = pos.z; z < pos.z + castleDepth; z++) {
    for (let y = pos.y; y < pos.y + wallHeight; y++) {
      await placeBlock("stone_bricks", pos.x, y, z);
      await placeBlock("stone_bricks", pos.x + castleWidth - 1, y, z);
    }
  }
}

// Build the towers
async function buildTowers() {
  const towerPositions = [
    { x: pos.x, z: pos.z },
    { x: pos.x + castleWidth - 1, z: pos.z },
    { x: pos.x, z: pos.z + castleDepth - 1 },
    { x: pos.x + castleWidth - 1, z: pos.z + castleDepth - 1 }
  ];

  for (let tower of towerPositions) {
    for (let dx = -towerRadius; dx <= towerRadius; dx++) {
      for (let dz = -towerRadius; dz <= towerRadius; dz++) {
        for (let y = pos.y; y < pos.y + towerHeight; y++) {
          const distance = Math.sqrt(dx * dx + dz * dz);
          if (distance <= towerRadius) {
            await placeBlock("stone_bricks", tower.x + dx, y, tower.z + dz);
          }
        }
      }
    }
  }
}

// Build the crenellations
async function buildCrenellations() {
  for (let x = pos.x; x < pos.x + castleWidth; x++) {
    if ((x - pos.x) % 2 === 0) {
      await placeBlock("stone_brick_wall", x, pos.y + wallHeight, pos.z);
      await placeBlock("stone_brick_wall", x, pos.y + wallHeight, pos.z + castleDepth - 1);
    }
  }

  for (let z = pos.z; z < pos.z + castleDepth; z++) {
    if ((z - pos.z) % 2 === 0) {
      await placeBlock("stone_brick_wall", pos.x, pos.y + wallHeight, z);
      await placeBlock("stone_brick_wall", pos.x + castleWidth - 1, pos.y + wallHeight, z);
    }
  }
}

// Add doors and torches
async function addDecorations() {
  await placeBlock("oak_door", pos.x + Math.floor(castleWidth / 2), pos.y, pos.z);
  await skills.placeBlock(bot, "torch", pos.x + castleWidth / 2, pos.y + 3, pos.z - 1, "side");
}

// Build the staircases inside the towers
async function buildStaircases() {
  const towerCorners = [
    { x: pos.x + 1, z: pos.z + 1 },
    { x: pos.x + castleWidth - 2, z: pos.z + 1 },
    { x: pos.x + 1, z: pos.z + castleDepth - 2 },
    { x: pos.x + castleWidth - 2, z: pos.z + castleDepth - 2 }
  ];

  for (let corner of towerCorners) {
    for (let y = pos.y; y < pos.y + towerHeight; y++) {
      await placeBlock("oak_stairs", corner.x, y, corner.z++);
    }
  }
}

// Build each part of the castle
async function buildCastle() {
  await buildWalls();
  await buildTowers();
  await buildCrenellations();
  await addDecorations();
  await buildStaircases();
}

buildCastle();

