async function buildGlassDome(bot) {
    const radius = 5;  // Radius of the dome.
    const position = await world.getPosition(bot);  // Get current position.
    const centerX = position.x;
    const centerY = position.y + radius;
    const centerZ = position.z;

    for (let x = -radius; x <= radius; x++) {
        for (let y = -radius; y <= radius; y++) {
            for (let z = -radius; z <= radius; z++) {
                if (x * x + y * y + z * z <= radius * radius) {
                    await skills.placeBlock(bot, "glass", centerX + x, centerY + y, centerZ + z);    
                }
            }
        }
    }
}

